<script setup>
import { ref, reactive, watch, onMounted } from 'vue';
import Icon from '../components/Icon.vue';
import Modal from '../components/Modal.vue';
import { state, isDemo, notify, report, refresh, signOut } from '../lib/workspace.js';
import { post, saveAuth } from '../lib/api.js';
const tab = ref(state.route.params.tab || 'model'), items = ref([]), keyword = ref(''), loading = ref(false), error = ref(''), dialog = ref(''), busy = ref(false), target = ref(null), form = reactive({});
const profile = reactive({ userName: state.auth?.userName || '', oldPassword: '', newPassword: '' }), avatar = ref(null);
const sampleModels = [{ apiId: 'demo-api', modelId: 'demo-model', modelName: 'DeepSeek V3', modelType: 'chat', apiBaseUrl: 'https://api.example.com', apiCompletionPath: '/v1/chat/completions', apiKey: 'demo-placeholder' }];
const sampleTools = [{ mcpId: 'demo-mcp', mcpName: '网页检索', mcpType: 'sse', mcpDesc: '连接公开信息，为研究补充上下文。', mcpParam: '{"baseUri":"https://mcp.example.com","sseEndPoint":"/sse"}', mcpSecret: '' }];
async function load() {
  error.value = ''; if (tab.value === 'profile') return; loading.value = true;
  try { items.value = isDemo.value ? (tab.value === 'model' ? sampleModels : sampleTools).filter(i => (i.modelName || i.mcpName).toLowerCase().includes(keyword.value.toLowerCase())) : (await post('/user/' + tab.value + '/list', { query: { keyword: keyword.value } })) || []; }
  catch (e) { error.value = e.message; } finally { loading.value = false; }
}
function open(item = null) {
  target.value = item; Object.keys(form).forEach(k => delete form[k]);
  Object.assign(form, tab.value === 'model' ? { modelName: '', modelType: 'chat', apiBaseUrl: '', apiKey: '', apiCompletionPath: '/v1/chat/completions' } : { mcpName: '', mcpType: 'sse', mcpDesc: '', mcpParam: '{"baseUri":"","sseEndPoint":"/sse"}', mcpSecret: '' });
  if (item) for (const key of Object.keys(form)) form[key] = item[key] || '';
  error.value = ''; dialog.value = 'edit';
}
async function save() {
  if (busy.value) return; error.value = '';
  if (tab.value === 'mcp') { try { const param = JSON.parse(form.mcpParam); if (form.mcpType === 'sse' && (!param.baseUri || !param.sseEndPoint)) throw new Error(); if (form.mcpType === 'stdio' && !param.command) throw new Error(); } catch { error.value = form.mcpType === 'sse' ? '请提供包含 baseUri、sseEndPoint 的有效 JSON 配置' : '请提供包含 command 的有效 JSON 配置'; return; } }
  busy.value = true;
  try {
    const key = tab.value === 'model' ? 'apiId' : 'mcpId', payload = { ...form, ...(target.value ? { [key]: target.value[key] } : {}) };
    if (!isDemo.value) { await post('/user/' + tab.value + '/' + (target.value ? 'update' : 'insert'), { json: payload }); await refresh(); }
    else { const list = tab.value === 'model' ? sampleModels : sampleTools; const safe = { ...payload, [key]: target.value?.[key] || 'demo-config-' + Date.now(), apiKey: 'demo-placeholder', mcpSecret: '' }; if (target.value) list.splice(list.indexOf(target.value), 1, safe); else list.push(safe); }
    form.apiKey = ''; form.mcpSecret = ''; dialog.value = ''; await load(); notify(isDemo.value ? '演示配置已保存，输入的密钥不会保存或使用' : '配置已保存，连接将在装配时建立');
  } catch (e) { error.value = e.message; } finally { busy.value = false; }
}
async function remove() { if (busy.value) return; busy.value = true; try { const key = tab.value === 'model' ? 'apiId' : 'mcpId'; if (!isDemo.value) { await post('/user/' + tab.value + '/delete', { query: { [key]: target.value[key] } }); await refresh(); } else { const list = tab.value === 'model' ? sampleModels : sampleTools; list.splice(list.indexOf(target.value), 1); } dialog.value = ''; await load(); notify('配置已删除'); } catch (e) { error.value = e.message; } finally { busy.value = false; } }
async function saveProfile() {
  if (busy.value) return;
  if (isDemo.value) { state.authOpen = true; return; }
  error.value = ''; if (!!profile.oldPassword !== !!profile.newPassword) { error.value = '修改密码时，请同时填写原密码和新密码'; return; }
  busy.value = true;
  try { const data = { userName: profile.userName, ...(profile.oldPassword ? { oldPassword: profile.oldPassword, newPassword: profile.newPassword } : {}) }; const formData = new FormData(); formData.append('profile', new Blob([JSON.stringify(data)], { type: 'application/json' })); if (avatar.value) formData.append('avatar', avatar.value); const auth = await post('/user/profile/edit', { form: formData }); saveAuth(auth); state.auth = auth; profile.oldPassword = ''; profile.newPassword = ''; avatar.value = null; notify('个人资料已更新'); }
  catch (e) { error.value = e.message; } finally { busy.value = false; }
}
watch(tab, () => { keyword.value = ''; load(); });
onMounted(async () => { load(); if (!isDemo.value) { try { const auth = await post('/user/profile/query'); saveAuth(auth); state.auth = auth; profile.userName = auth.userName; } catch (e) { report(e); } } });
</script>
<template>
  <div class="page settings-page"><header class="page-heading"><div><div class="eyebrow">A WORKSPACE THAT FEELS LIKE YOU</div><h1>把工作空间，调成你的样子</h1><p>管理模型、连接工具，照顾好每一个小细节。</p></div></header><div class="settings-layout"><aside class="settings-nav"><button :class="{ active: tab === 'model' }" @click="tab = 'model'"><Icon name="layers" :size="18" />模型服务</button><button :class="{ active: tab === 'mcp' }" @click="tab = 'mcp'"><Icon name="plug" :size="18" />工具连接</button><button :class="{ active: tab === 'profile' }" @click="tab = 'profile'"><Icon name="settings" :size="18" />个人资料</button><button v-if="!isDemo" class="logout-item" @click="signOut"><Icon name="logout" :size="18" />退出登录</button></aside><div class="settings-content"><template v-if="tab !== 'profile'"><div class="section-heading"><div><h2>{{ tab === 'model' ? '给你的 AI 伙伴选择大脑' : '连接能力，让行动更进一步' }}</h2><p class="section-subtitle">{{ tab === 'model' ? '添加兼容的模型服务，供智能体使用。' : '通过 MCP 为智能体提供检索、阅读和其他工具。' }}</p></div><button class="primary-button" @click="open()"><Icon name="plus" :size="16" />{{ tab === 'model' ? '添加模型' : '连接工具' }}</button></div><form class="search-field settings-search" @submit.prevent="load"><Icon name="search" :size="16" /><input v-model="keyword" :placeholder="tab === 'model' ? '搜索模型' : '搜索工具'" aria-label="搜索配置" /><button type="submit" class="text-button">搜索</button></form><div v-if="isDemo" class="demo-notice">当前为示例配置，未连接真实服务。</div><div v-if="loading" class="loading-placeholder">正在读取配置…</div><div v-else class="resource-list"><article v-for="item in items" :key="item.apiId || item.mcpId" class="resource-card"><span class="agent-avatar" :class="tab === 'model' ? 'sage' : 'lavender'"><Icon :name="tab === 'model' ? 'layers' : 'plug'" :size="25" /></span><div class="resource-description"><h3>{{ item.modelName || item.mcpName }}<span class="tag sage">{{ item.modelType || item.mcpType }}</span></h3><p>{{ tab === 'model' ? item.apiBaseUrl : item.mcpDesc }}</p><small v-if="tab === 'model'">API Key <span class="masked-key">•••• •••• ••••</span></small></div><div class="row"><button class="icon-button" aria-label="编辑配置" @click="open(item)"><Icon name="pen" :size="17" /></button><button class="icon-button" aria-label="删除配置" @click="target = item; dialog = 'delete'; error = ''"><Icon name="trash" :size="17" /></button></div></article><div v-if="!items.length" class="empty-state"><Icon :name="tab === 'model' ? 'layers' : 'plug'" :size="36" /><h2>连接你的第一个{{ tab === 'model' ? '模型' : '工具' }}</h2><p>从这里为你的智能体添加新的能力。</p></div></div><div class="info-note">{{ tab === 'model' ? '模型服务与对话客户端分别管理。自由对话的客户端由服务端提供；此处添加的模型用于创建和配置智能体。' : '保存配置后，工具会在装配时解析并建立连接。保存成功不代表工具已经连接。' }}</div></template><template v-else><section class="paper-panel"><h2>个人资料</h2><div v-if="isDemo" class="empty-state"><span class="profile-avatar large-avatar">Z</span><h2>让这里真正属于你</h2><p>登录后保存个人资料，连接真实模型与工作空间。</p><button class="primary-button" @click="state.authOpen = true">登录 ZFlow <Icon name="arrow" :size="17" /></button></div><form v-else class="form-stack" @submit.prevent="saveProfile"><div class="profile-edit-avatar"><span class="profile-avatar large-avatar">{{ state.auth.userName?.slice(0,1) }}</span><label>更换头像<input type="file" accept="image/*" @change="avatar = $event.target.files[0]" /></label></div><label>用户名<input v-model="profile.userName" required autocomplete="username" /></label><div class="form-grid"><label>原密码 · 不修改可留空<input v-model="profile.oldPassword" type="password" autocomplete="current-password" /></label><label>新密码<input v-model="profile.newPassword" type="password" autocomplete="new-password" /></label></div><div class="form-actions"><button class="primary-button" :disabled="busy">{{ busy ? '保存中…' : '保存个人资料' }}</button></div></form></section></template><div v-if="error && !dialog" class="form-error">{{ error }}</div></div></div></div>
  <Modal v-if="dialog === 'edit'" :title="(target ? '编辑' : '添加') + (tab === 'model' ? '模型服务' : '工具连接')" @close="!busy && (dialog = '', form.apiKey = '', form.mcpSecret = '')"><form class="modal-body form-stack" @submit.prevent="save"><template v-if="tab === 'model'"><label>模型名称<input v-model="form.modelName" required placeholder="服务商提供的模型名称" /></label><label>模型类型<input v-model="form.modelType" required placeholder="例如：chat" /></label><label>服务地址<input v-model="form.apiBaseUrl" type="url" required placeholder="https://api.example.com" /></label><label>API Key<input v-model="form.apiKey" type="password" required autocomplete="off" placeholder="输入模型服务密钥" /></label><label>对话路径<input v-model="form.apiCompletionPath" required placeholder="/v1/chat/completions" /></label></template><template v-else><label>工具名称<input v-model="form.mcpName" required placeholder="例如：网页检索" /></label><label>传输方式<select v-model="form.mcpType"><option value="sse">SSE</option><option value="stdio">stdio</option></select></label><label>能力描述<textarea v-model="form.mcpDesc" required rows="2" placeholder="描述该工具可以完成什么" /></label><label>连接配置 · JSON<textarea v-model="form.mcpParam" required rows="5" spellcheck="false" /><small>{{ form.mcpType === 'sse' ? '需要 baseUri 和 sseEndPoint 字段。' : '需要 command，可选 args、env。' }}</small></label><label>访问凭据 · 可选<input v-model="form.mcpSecret" type="password" autocomplete="off" /></label></template><div v-if="isDemo" class="info-note">演示模式不会使用或保存输入的密钥。</div><div v-if="error" class="form-error">{{ error }}</div><button class="primary-button" :disabled="busy">{{ busy ? '保存中…' : '保存配置' }}</button></form></Modal>
  <Modal v-if="dialog === 'delete'" title="删除这项配置？" @close="!busy && (dialog = '')"><div class="modal-body form-stack"><p class="small muted">确认删除「{{ target.modelName || target.mcpName }}」？依赖此配置的智能体可能受到影响。</p><div v-if="error" class="form-error">{{ error }}</div><button class="danger-button" :disabled="busy" @click="remove">确认删除配置</button></div></Modal>
</template>
